import{_ as r,a}from"./chunks/023231ca64da295471c7.BcsgMTqh.js";import{_ as o,C as l,o as i,c as n,j as p,a as s,E as h,a6 as m}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"价值百万美元的创作者——如何将你的兴趣变现","description":"","frontmatter":{"title":"价值百万美元的创作者——如何将你的兴趣变现","originalTitle":"The $1 Million Dollar Creative – How To Monetize Your Interests","date":"2024-05-18","originalUrl":"https://thedankoe.com/letters/the-1-million-dollar-creative-how-to-monetize-your-interests/","minutes":12,"sourceHash":"b6fb9f9a7355be93f3d2dc09a91ae6c08e86eec80baca5353fad16a9e24a2d39","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-1-million-dollar-creative-how-to-monetize-your-interests/"}]]},"headers":[],"relativePath":"letters/the-1-million-dollar-creative-how-to-monetize-your-interests.md","filePath":"letters/the-1-million-dollar-creative-how-to-monetize-your-interests.md"}'),c={name:"letters/the-1-million-dollar-creative-how-to-monetize-your-interests.md"};function d(u,e,g,_,f,b){const t=l("ArticleMeta");return i(),n("div",null,[e[0]||(e[0]=p("h1",{id:"价值百万美元的创作者——如何将你的兴趣变现",tabindex:"-1"},[s("价值百万美元的创作者——如何将你的兴趣变现 "),p("a",{class:"header-anchor",href:"#价值百万美元的创作者——如何将你的兴趣变现","aria-label":'Permalink to "价值百万美元的创作者——如何将你的兴趣变现"'},"​")],-1)),h(t),e[1]||(e[1]=m('<p><a href="https://www.youtube.com/embed/hSi6tr0ZUSQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>我小时候被人骗了。</p><p>我有种感觉，你也是。</p><p>我记得在我父母离婚后，我坐在我爸那间破旧的公寓里，盯着一台旧笔记本电脑的屏幕，上面开着亚利桑那州立大学（Arizona State University）的网站，心里琢磨着我到底要学点什么，并为之投入余生。</p><p>18岁那年，我面临着一个几乎不可能的决定。在我甚至还没有真正拥有自己的人生时，我就被迫要确切地知道我想从生活中得到什么。我被迫为我未来40多年的人生选择一个职业起点。我被迫选择一个似乎能“为我铺就美好未来”的东西，否则我就得承担后果——字面意义上的一大笔学生贷款。</p><p>对大多数人来说，他们会选择最能赚钱的职业……但那是个谎言。</p><p>还有些人，他们会选择能赢得他人尊重的职业……但那也是个谎言。</p><p>至于剩下的人，他们会选择自认为最喜欢的职业……但这同样是个谎言。</p><p>你的父母和老师向你兜售了一个幻觉，而他们自己也是这个幻觉的受害者。</p><p>他们是否拥有学位，对他们的收入、地位或乐趣几乎没有影响。学位可能敲开了一些机会的大门，但最终，是他们的个人选择带来了更高的收入、地位或乐趣水平。这世上有大把富有的辍学者，也有无数破产的毕业生。</p><p>人们开始渐渐醒悟：对于明智的人来说，传统的老路已经行不通了。</p><p>正如艾伦·瓦茨（Alan Watts）所说：“明智的人靠做自己喜欢的事来赚钱。”</p><p>如果你在读这篇文章，我假设你骨子里是个创作者。</p><p>你不在乎赚上几十亿，你在乎的是赚到足够多的钱，让你能随心所欲地做想做的事。</p><p>你不在乎典型企业家的那种拼命与折腾，你在乎的是休息、空闲时间，以及有意义的工作。</p><p>但你被骗了。</p><p>你去上学，找了份工作，然后意识到了一些事。</p><ul><li><strong>你不知道如何在工作<em>之外</em>将你的激情、兴趣或技能变现。</strong> 换句话说，你不明白赚钱就像你学过的任何其他技能一样，是一套技能组合，但你却指望你的雇主来喂给你这些技能。</li><li><strong>你学会了那些能“让你赚最多钱”的技能，</strong> 却发现你的收入潜力有着硬性上限，而这个上限是雇主为你设定的。你赚多少取决于你为该技能选择的载体，而打工通常不是最好的长期载体。</li><li><strong>你在用时间换钱，而技术最终会让这些任务变得更高效。</strong> 你所做的工作在未来会变得越来越不值钱，我们要么接受大幅降薪，要么直接被炒鱿鱼。技术降低了可重复任务的成本，这样我们就能专注于解决创造性和人类特有的问题。</li></ul><p>这正是我在这封信里想帮你改变的。</p><p>我想向你证明，靠简单的逻辑和数学，做你喜欢的事赚到100万美元是完全可能的。这是一封半实操性质的信，但信念先于行动，所以我们要稍微敲打一下你的大脑，把你思维过程中那些削弱力量的信念清理掉。</p><p>我想向你展示应该把重心放在哪里，这样你才不会陷入一个名叫“客户工作”的全新朝九晚五的陷阱。</p><p>我想让你完全掌控自己工作多少、赚多少钱，以及你能从这两者中获得多少满足感。</p><h2 id="杠杆工作——创作者的定义" tabindex="-1">杠杆工作——创作者的定义 <a class="header-anchor" href="#杠杆工作——创作者的定义" aria-label="Permalink to &quot;杠杆工作——创作者的定义&quot;">​</a></h2><blockquote><p>如果工作不需要创造力，那就委派出去、将其自动化，或者干脆别干。——纳瓦尔（Naval）</p></blockquote><p>创作者不是拥有某种特定技能，然后会被机器人以更低价格淘汰的人。</p><p>创作者不是设计师、电影制作人、画家、作家、摄影师，或任何带有特定限制的身份。</p><p>创作者是将生活的历程投射在他们作品中的人。</p><p>创作者是为了追求某个目标（通常以项目的形式），动用必要的技能、知识、经验和灵感的任何组合来解决问题的人。</p><p>如果你做着一份自己讨厌的设计师工作，我敢说你算不上真正的创作者，哪怕你的职位头衔和身份标榜你是（因为你是个花哨的“设计师”）。</p><p>你并没有把这份你讨厌的工作视为需要优先解决的问题。</p><p>你没有划出时间去做具有最高杠杆的工作，好让你摆脱那份工作，重新夺回对时间和收入的控制权。你不够有创造力去解决真正的问题，所以你只顾着埋头干活，在屏幕上造出一些漂亮的像素，去解决雇主派给你的问题。</p><p>我并不反对打工，但我看清了它的本质：一块垫脚石。</p><p>工作有助于获取技能和行业知识，但它也会损害人的心理，滋生自满情绪。</p><p>在打工时，几乎可以肯定总有一天你会停止解决新的问题。你会被困在日复一日解决同样问题的死循环里。而且这些问题一开始根本不是你选来解决的。你会感到无聊，开始浪费时间，但到那时，你已经背负了太多的责任和坏习惯，以至于你总是感到视野狭隘、压力重重，因此你独立发现和解决问题的能力会变得异常艰难。</p><p>生活就是一连串永无休止的问题。</p><p>问题是使命的另一极，两者缺一不可。</p><p>解决问题的方案是有价值的。</p><p>当你停止解决新问题时，你的思维就停止了扩张。</p><p>每解决一个问题，你的心智就会达到一个新的高度，因为你必须拉开视角进入未知领域，收集资源，并利用大脑的创造力进入下一个阶段。这是在<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》</a>（The Art Of Focus）中的关键一课。</p><p>换句话说，一份工作，或者仅仅是你的舒适区，可能就是最好版本的你的早夭。事实上，我甚至不会说它是早夭。它是朝着最坏版本的你缓慢而痛苦地衰退。解决问题是你扭转大脑熵增的方式。如果你没有新问题去解决，你就会慢慢溺死在混乱中，感到无聊、迷茫和焦虑，直到痛苦到迫使你改变现状，或者接受早夭。</p><p>我希望你别等到那个地步。</p><p>创作者是将杠杆工作作为终极目标的人。</p><p>也就是说，找出那些能以最小努力带来最大成果的工作。</p><p>对大多数人来说，你所寻找的“成果”无非是更多的钱、更多的时间以及更多的成就感。</p><p>以下是实现所有这些成果的步骤。</p><h2 id="价值百万美元的创作者" tabindex="-1">价值百万美元的创作者 <a class="header-anchor" href="#价值百万美元的创作者" aria-label="Permalink to &quot;价值百万美元的创作者&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>我曾经一直相信，热情存在于某项特定技能中。</p><p>我试图在网页设计、数字艺术和编程中寻找那份热情。但每一次，我留下的只有空虚感。</p><p>直到我决定掌控自己的生活，弄清楚我想要的未来到底是什么，并开始不懈追求它时，我才终于明白什么是真正的创作者。</p><p><em>热情存在于创造你愿景的过程中。</em></p><p>你可以享受沿途所使用的某项技能，但如果你沉迷其中，或者将其教条化，把它当成自己的身份标签，你就会被困住。</p><p>你的热情不在于当一名设计师，而在于设计能让你解决的问题（直到你的生活和工作限制了你能解决哪些问题为止）。</p><p>热情是将能量投入到一个目标中。你可能对掌握某项技能的旅程充满热情，但一旦你精通了它，热情就会消退。你必须通过将能量引导到能够实现你愿景的技能、目标和项目中，来保持这种热情。你的愿景就是一个无尽的能量储备库。</p><p>如果你想通过兴趣变现，作为一人企业达到100万美元，你就必须得接受去学一些你可能不想学的技能，去做一些你可能不想做的工作。</p><p>到头来，这会比因为固执己见、不愿学习必要技能而永远无法实现愿景，带给你多得多的成就感。</p><h3 id="_1-选择愿景-而不是技能" tabindex="-1">1) 选择愿景，而不是技能 <a class="header-anchor" href="#_1-选择愿景-而不是技能" aria-label="Permalink to &quot;1) 选择愿景，而不是技能&quot;">​</a></h3><p>如果没有愿景，你就会迷失。你无法创造出成果，所以注定只能像机器一样生活，接受被设定好的结局。</p><p>你在生活任何领域做出的每一个决定，都必须通过你的愿景来过滤。只有这样，你才能为行动赋予意义，把干扰降到最低。</p><p>原原本本地写下你究竟想从生活中得到什么。</p><p>不要遗漏任何细节，但要明白这是一个迭代的过程。</p><p>你不可能第一次就写对，甚至可能永远写不对。但那不是重点。花30分钟先构思一个最小可行性愿景。</p><p>经常回头看看它，增减修补，因为你的欲望不可避免地会随着你的失败而改变。</p><p>你的愿景就是你的过滤器，用来筛选该做什么工作、该学什么技能以及该做哪些决定。</p><p>再说一次，如果你没有愿景，无论现在看似有多清晰，<em>你都是迷失的</em>。</p><h3 id="_2-叠加面向未来的技能" tabindex="-1">2) 叠加面向未来的技能 <a class="header-anchor" href="#_2-叠加面向未来的技能" aria-label="Permalink to &quot;2) 叠加面向未来的技能&quot;">​</a></h3><p>你总在担心该学什么职业技能才能在20年后依然吃香，因为你把注意力放在了技能的可行性上，而不是愿景上。</p><p>如果你想确保未来的安稳，你需要一套基础的技能组合，包括：</p><ul><li><strong>营销与销售</strong>——如果你不知道如何吸引和说服别人，你永远无法得到你想要的东西，你唯一的选择就是眼巴巴等着雇主（或政府）施舍给你。</li><li><strong>写作与思考</strong>——这是沟通你独特心智中价值的能力。也是让你脱颖而出、走到众人面前的基础。</li><li><strong>创业精神</strong>——将未来掌握在自己手中、为生存而狩猎，并打造出你想在这个世界上看到的（同时也是别人在乎的）产品的过程。</li></ul><p>当你把这些与在创造愿景时学到的各种兴趣结合起来，你将势不可挡。我在免费的<a href="https://theone-personbusiness.com/" target="_blank" rel="noreferrer">一人企业基础迷你课程</a>（One-Person Business Foundations mini-course）里教授这些基础知识。</p><h3 id="_3-用实验去解决问题" tabindex="-1">3) 用实验去解决问题 <a class="header-anchor" href="#_3-用实验去解决问题" aria-label="Permalink to &quot;3) 用实验去解决问题&quot;">​</a></h3><p>自我实验是彻底解决你自身问题的唯一途径。</p><p>自我实验也是创造出让其他人受益的独特解决方案的唯一方法。</p><p>你的任务是：</p><ul><li><strong>研究他人已经取得成功的流程。</strong> 值得庆幸的是，你只需简单搜索就能找到这些。</li><li><strong>实验各种不同的技术。</strong> 实施你学到的流程，并尝试取得成果。</li><li><strong>找出规律和原则。</strong> 留意它们之间的相似之处，并加大力度投入其中。</li><li><strong>创造你自己的流程。</strong> 将你学到的知识根据你自己独特的生活方式和处境进行量身定制。</li><li><strong>通过将其传承下去来为真正的教育做贡献。</strong> 传授给别人在学校里学不到的、以批判性思维为根本基础的教育。</li></ul><p>如果你解决过自己生活中的某个问题，你就有资格开始创业了。</p><h3 id="_4-成为一个价值创作者" tabindex="-1">4) 成为一个价值创作者 <a class="header-anchor" href="#_4-成为一个价值创作者" aria-label="Permalink to &quot;4) 成为一个价值创作者&quot;">​</a></h3><p>如今对新手创作者来说，最好的载体就是成为一名创作者（creator）。</p><p>不是网红，而是创作者。准确地说，是一个价值创作者。</p><p>一个基于自己热爱的兴趣，通过让这些兴趣对他人也变得有趣，从而成为价值源泉的人。</p><p>你要成为你这些兴趣的<em>源头</em>，以此吸引受众关注它们。</p><p>你通过以下方式做到这一点：</p><ul><li><strong>教育</strong> – 以一种帮助人们实现符合你愿景目标的方式来传授你的兴趣。</li><li><strong>娱乐</strong> – 注入一丝个人魅力，以吸引像你一样的人（也就是你最能提供帮助的人）。</li><li><strong>启发</strong> – 向人们展示你所构建的东西，让他们看到一切皆有可能。</li></ul><p>社交媒体不仅仅是你手机上的一个应用。</p><p>它是全新数字社会的城市广场。</p><p>是的，你可能用它来刷一些毫无意义的内容来麻痹大脑，但其他人却把它当作学校不教的教育资源，以此达到常规社会无法企及的高度。</p><p>价值创造者是那些投身于自己兴趣的人，他们将探索这些兴趣作为毕生的事业，并将这些信息提炼成教育。</p><p>这就是我所教授的一人企业（one-person business）模式。</p><p>创作社交媒体内容，在<em>你的名下</em>建立分发渠道。</p><p>在商业中，分发渠道 = 自由。</p><p>受众 = 分发渠道。</p><p>把这句话死死刻进你的脑子里：</p><p>如果没有<em>人</em>愿意为你以产品形式提供的价值而<em>付钱给你</em>，你就无法赚到（<em>受你控制的</em>）钱。</p><p>如果你永远意识不到这一点，你就别无选择，只能一辈子打工，让你的雇主替你做这件事。</p><h3 id="_5-变现你的头脑-而不是你的时间" tabindex="-1">5) 变现你的头脑，而不是你的时间 <a class="header-anchor" href="#_5-变现你的头脑-而不是你的时间" aria-label="Permalink to &quot;5) 变现你的头脑，而不是你的时间&quot;">​</a></h3><p>价值创造者是这样一群人：</p><ul><li>变现他们的头脑，而不是他们的时间，这样他们就能在保持单枪匹马的同时不限制自己的收入。一个人的劳动力是无法规模化扩展的，但他们头脑的创造力可以。</li><li>研究他们痴迷的事物，并通过写作、视频及其他互联网内容来提炼他们的所学。</li><li>将积累的知识和经验转化为数字产品（或者实体产品，一旦你有足够的现金流来维持……但每个人都应该拥有一个能替代其收入、覆盖生活开销的数字产品），并以此获得报酬。</li></ul><p>这正是我们在我的新课程 <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">心智变现 (Mental Monetization)</a> 中教你如何做的事情，以此来变现你的创造性工作。它将于 6 月 3 日上线。趁着涨价前赶紧预购吧。</p><p>产品是最高形式的杠杆。</p><p>它们在你睡觉时都能卖出去。</p><p>你不需要像做服务或客户工作那样，花费时间去交付你所提供的价值。</p><p>你只需构建一次，然后凭借你的技能尽可能多地卖出它。</p><h3 id="_6-将其变成-100-万美元" tabindex="-1">6) 将其变成 100 万美元 <a class="header-anchor" href="#_6-将其变成-100-万美元" aria-label="Permalink to &quot;6) 将其变成 100 万美元&quot;">​</a></h3><p>作为一名价值创造者，你的杠杆是：</p><ul><li><strong>写作</strong> – 通过教育人们你的兴趣如何帮助他们实现目标，以此吸引一批受众。这些文字可以被重新打造成帖子、时事通讯、YouTube 脚本，甚至毫不夸张地说是任何类型的其他内容。从写作开始。（<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">两小时作者 (2 Hour Writer)</a> 教的就是这个）。</li><li><strong>推广</strong> – 如果你不推广自己的产品，你是赚不到钱的。在社交媒体上推广你的邮件列表。在你的邮件列表上推广你的产品。</li><li><strong>迭代</strong> – 关注那些表现得比其他更好的文字和推广内容。在实践中不断改进，以提高它们的有效性。</li></ul><p>毫不夸张地说，这是你作为一个单打独斗的人实现 100 万美元目标的唯一需要做的事。</p><p>你有一款卖得出去的产品。</p><p>你拥有一个正在增长的受众群体。</p><p>如果你能持续增加受众并卖出产品……你能赚多少钱真的完全取决于你自己。这只是简单的数学问题。</p><p>如果你能赚 1 美元，你就能赚 100 万美元。</p><p>如果你能获得 1 个粉丝，你就能获得 100 万个粉丝。</p><p>这里唯一的陷阱，就是忘记你是一个创作者。</p><p>如果你的受众停止增长，这是个问题，解决它。</p><p>如果你的产品卖不动了，这是个问题，解决它。</p><p>如果你不知道怎么解决……技能问题。</p><h3 id="_6-休息的重要性" tabindex="-1">6) 休息的重要性 <a class="header-anchor" href="#_6-休息的重要性" aria-label="Permalink to &quot;6) 休息的重要性&quot;">​</a></h3><p>你无法用狭隘的头脑去发现新问题。</p><p>工作使大脑收缩，休息使大脑扩张。</p><p>在休息时，你的大脑会启动默认模式网络（Default Mode Network）。</p><p>我们不需要深入探讨技术细节，但当你在休息时，你的大脑会<em>更加</em>活跃，并试图建立连接，将想法吐到你的显意识中。</p><p>听说过“洗澡时的灵感”吗？</p><p>那正是这个过程的产物。</p><p>如果你想持续产生能够带来最高杠杆工作的好主意……那就停止工作。</p><p>在各个工作时间块之间安排散步。去健身房。腾出专门的阅读时间。和朋友去吃晚餐。做任何不是工作的事情……特别是别去思考工作。</p><h3 id="_7-去他-的瞎忙" tabindex="-1">7) 去他*的瞎忙 <a class="header-anchor" href="#_7-去他-的瞎忙" aria-label="Permalink to &quot;7) 去他\\*的瞎忙&quot;">​</a></h3><p>如果这项工作无法推动你朝着愿景取得实质性进展，就停止做它。</p><p>瞎忙只是大多数人喜欢陷入的另一种干扰罢了。</p><p>你的心理天生就是为了狩猎而设计的。</p><p>所以，正如纳瓦尔（Naval）会说的那样，像狮子一样工作。</p><p>或者，用我的话来说，运用战术性压力。</p><ul><li><strong>坐下</strong>，让愿景积淀。</li><li><strong>等待</strong>，直到你看到猎物。</li><li><strong>冲刺</strong>，把工作完成。</li><li><strong>进食</strong>，享受生活与休息。</li></ul><p>这与我们从小被灌输的观念背道而驰。接受这才是创作者的工作方式，是需要时间的。</p><p>被死死框在朝九晚五的整齐日程里，对于骨子里是创作者和企业家的人来说，简直就是活地狱。</p><p>这封信就到这里，感谢你的阅读。</p><p>– Dan</p><hr><p><a href="/en/letters/the-1-million-dollar-creative-how-to-monetize-your-interests">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',138))])}const x=o(c,[["render",d]]);export{P as __pageData,x as default};
